    def count_ways(n, target):
        @lru_cache(maxsize=None)
        def dp(turn, current):
            if turn == 0:
                return 1 if current == target else 0
            total = 0
            for s in range(-k, k + 1):
                total = (total + dp(turn - 1, current + s)) % MOD
            return total
        return dp(n, target)

    @lru_cache(maxsize=None)
    def solve(ml, mx):
        if ml == 0:
            return 1
        if mx <= 0:
            return 0

        res = 0
        for d in range(-2 * k, 2 * k + 1):
            if d > 0:
                res = (res + solve(ml - 1, mx - 1)) % MOD
            elif d == 0:
                res = (res + solve(ml - 1, mx)) % MOD
            else:
                res = (res + solve(ml - 1, mx + 1)) % MOD
        return res

    max_score = a + t * k
    min_score = a - t * k
    lex_max = b + t * k
    lex_min = b - t * k

    result = 0
    for m in range(lex_max, max_score + 1):
        result = (result + count_ways(t, m - a)) % MOD
    for l in range(lex_min, m + 1):
        result = (result - count_ways(t, l - b) + MOD) % MOD

