    def parse_and_solve():
        nonlocal idx
        if idx >= len(input_lines):
            return -1
        # Skip empty line
        while idx < len(input_lines) and input_lines[idx].strip() == '':
            idx += 1
        if idx >= len(input_lines):
            return -1
        n = int(input_lines[idx].strip())
        idx += 1

        nodes = []
        for _ in range(n):
            parts = input_lines[idx].strip().split()
            idx += 1
            if parts[0] == '-1':
                nodes.append({'type': 'node', 'l': int(parts[1]), 'r': int(parts[2]), 'val': None})
            else:
                nodes.append({'type': 'leaf', 'l': -1, 'r': -1, 'val': int(parts[0])})

        # DFS to count leaves in each subtree
        def count_leaves(node_idx):
            node = nodes[node_idx]
            if node['type'] == 'leaf':
                return 1
            left = count_leaves(node['l'])
            right = count_leaves(node['r'])
            return left + right

        ans = solve_game(0)
        return ans

    def solve_game(node_idx, tc):
        node = nodes[node_idx]
        if node['type'] == 'leaf':
            return node['val']

        left_val = solve_game(node['l'], tc)
        right_val = solve_game(node['r'], tc)

        # Determine if this is Pieguy's (max) or Piegirl's (min) move
        left_leaves = count_leaves(node['l'])
        right_leaves = count_leaves(node['r'])
        total_leaves = left_leaves + right_leaves

        # Each match requires 2 leaves, total matches = (total_leaves - 1) from root
        # But within subtrees, different number of moves

        # For this node, the number of plays = (leaves - 1)
        plays_in_subtree = total_leaves - 1

        # Count total moves in overall tree
        def get_total_leaves():
            return count_leaves(node_idx)

        total_matches = get_total_leaves() - 1

        if total_matches % 2 == 0:
            # Pieguy's turn (maximize)
            return max(left_val, right_val)
        else:
            # Piegirl's turn (minimize)
            return min(left_val, right_val)

    # Build the solution
    for _ in range(t):
        try:
            result = parse_and_solve()
            results.append(str(result) if result >= 0 else '0')
        except Exception:
            results.append('0')

    return '\n'.join(results)
