import sys

def nCr(m, r):
    if r < 0 or r > m:
        return 0
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i % 1000000007
    inv = [1] * (m + 1)
    for i in range(1, m + 1):
        inv[i] = inv[i - 1] * pow(i, 1000000007 - 2, 1000000007) % 1000000007
    def nCr(m, r):
        return fact[m] * inv[r] * inv[m - r] % 1000000007
    return nCr

MOD = 1000000007
fact = [1] * 2001
inv = [1] * 2001
for i in range(1, 2001):
    fact[i] = fact[i - 1] * i % MOD
for i in range(1, 2001):
    inv[i] = inv[i - 1] * pow(i, MOD - 2, MOD) % MOD

def nCrComb(m, r):
    if r < 0 or r > m:
        return 0
    return fact[m] * inv[r] * inv[m - r] % MOD

def solve(n, m):
    if n == 0 or m == 0:
        return 0
    ans = 0
    for length in range(1, n + 1):
        for t_offset in range(length + 1):
            l = 1
            r = l + length - 1
            if r > n:
                break
            t = l + t_offset
            prev = t - 1
            if prev < l:
                prev = l
            next_ = t + 1
            if r < next_:
                next_ = r
            if t == l:
                for i in range(1, m + 1):
                    for j in range(i + 1, m + 1):
                        ans = (ans + 2 * (nCrComb(m, 2))) % MOD
            else:
                left_contrib = (fact[t - l] * inv[2]) % MOD
                right_contrib = (fact[r - t] * inv[2]) % MOD
                case1 = nCrComb(t, 2) * nCrComb(m - t, 2)
                if left_contrib or right_contrib:
                    case1 = (case1 * (t - 2) * (m - t) % MOD + case2 * (t - 1) * m) % MOD
                ans = (ans + case1) % MOD
                case2 = nCrComb(t - 1, 2) * nCrComb(m - t + 1, 2)
                ans = (ans + case2) % MOD
    return str(ans)
