def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list for components
    # Nodes 1..m represent variables x_i (positive literals)
    # Nodes m+1..2m represent variables ¬x_i (negative literals)
    adj = [[] for _ in range(2 * m + 1)]

    def get_node(lit):
        # lit is original literal value (positive or negative)
        # Node 1..m = positive, m+1..2m = negative
        return lit if lit > 0 else m + abs(lit)

    def is_nogat(lit):
        return lit < 0

    def negate(lit):
        if lit > 0:
            return -(lit)
        return abs(lit)

    def convert(lit):
        # Convert literal to node index
        if lit > 0:
            return lit
        else:
            return m + abs(lit)

    def invers(lit):
        if lit > 0:
            return m + abs(lit)
        else:
            return abs(lit)

    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]

        # For clause (l1 OR l2 OR ... OR lk), add implications:
        # For each pair: ¬li -> lj and ¬lj -> li (for j != i)
        for i in range(k):
            val1 = literals[i]
            val2 = literals[(i + 1) % k]

            u = invers(val1)
            v = convert(val2)
            adj[u].append(v)

            u = invers(val2)
            v = convert(val1)
            adj[u].append(v)

    # Kosaraju's algorithm for strongly connected components
    visited = [False] * (2 * m + 1)
    order = []

    def dfs1(vertex):
        visited[vertex] = True
        for next_val in adj[vertex]:
            if not visited[next_val]:
                dfs1(next_val)
        order.append(vertex)

    for i in range(1, 2 * m + 1):
        if not visited[i]:
            dfs1(i)

    # Build reversed graph
    radj = [[] for _ in range(2 * m + 1)]
    for i in range(1, 2 * m + 1):
        for neighbor in adj[i]:
            radj[neighbor].append(i)

    component_id = [0] * (2 * m + 1)
    comp_count = 0
    visited = [False] * (2 * m + 1)

    def dfs2(vertex):
        visited[vertex] = True
        component_id[vertex] = comp_count
        for neighbor in radj[vertex]:
            if not visited[neighbor]:
                dfs2(neighbor)

    for i in range(n * 2, -1, -1):
        if not visited[order[i]]:
            dfs2(order[i])
            comp_count += 1

    # Check satisfiability
    for i in range(1, m + 1):
        u = convert(i)
        neg = invers(i)
        if component_id[u] == component_id[neg]:
            return "NO"

    # Build satisfying assignment (x_i is true if component_id[u] < component_id[neg])
    result = []
    for i in range(1, m + 1):
        u = convert(i)
        neg = invers(i)
        if component_id[u] < component_id[neg]:
            result.append("1")
        else:
            result.append("0")

    return "YES\n" + "".join(result)
