        if n < 2 or m < 2:
            results.append('0')
            continue

        count = 0
        valid_positions = set()

        for r in range(n):
            for c in range(m):
                # Check axis-aligned squares
                for size in range(2, min(n - r, m - c) + 1):
                    if can_form_axis_square(r, c, size, matrix, valid_positions):
                        count += 1
                        break

                # Check diagonal squares (rotated 45 degrees)
                part1 = r + size
                part2 = c + size - part1
                if part1 <= m - 1 and part2 <= n - 1 and part1 >= size and part2 >= size:
                    if can_form_diagonal_square(c, r, size, matrix, valid_positions):
                        count += 1
                        break

