def can_form_axis_square(r, c, size, matrix, visited):
    if size < 2:
        return False

    if not (0 <= r < len(matrix) and 0 <= c < len(matrix[0])):
        return False

    sr, sc = r, c
    br, bc = r + size - 1, c + size - 1

    border_coords = []
    border_coords.append((r, c))  # TL
    border_coords.append((r, c + size - 1))  # TR
    border_coords.append((r + size - 1, c))  # BL
    border_coords.append((r + size - 1, c + size - 1))  # BR

    for r in range(r + 1, r + size - 1):
        border_coords.append((r, c))  # left side
        border_coords.append((r, c + size - 1))  # right side

    for c in range(c + 1, c + size - 1):
        border_coords.append((r, c))  # top side
        border_coords.append((r, c + size - 1))  # bottom side

    for r, c in border_coords:
        if matrix[r][c] != '1':
            return False

    if len(visited) == 0:
        for r, c in border_coords:
            if ((r - 1, c - 1) in visited) or ((r - 1, c) in visited) or ((r - 1, c + 1) in visited) or \
               ((r, c - 1) in visited) or ((r, c + 1) in visited) or \
               ((r + 1, c - 1) in visited) or ((r + 1, c) in visited) or ((r + 1, c + 1) in visited):
                return False
        visited.add((br, bc))
        return True
    return False


def can_form_diagonal_square(c, r, size, matrix, visited):
    if size < 2:
        return False

    br, bc = c + size - 1, r + size - 1
    if not (0 <= br < len(matrix) and 0 <= bc < len(matrix[0])):
        return False

    border_coords = []
    border_coords.append((br - size // 2, br // 2))  # TL
    border_coords.append((br // 2, br - size // 2))  # TR
    border_coords.append((r + size - 1, r + size - 1))  # Bottom
    border_coords.append((r, c))  # Top

    for i in range(size):
        border_coords.append((r + i, c + i))
        border_coords.append((r + i, c + size - 1 - i))
        border_coords.append((r + size - 1 - i, c + i))
        border_coords.append((r + size - 1 - i, c + size - 1 - i))

    for r, c in border_coords:
        if matrix[r][c] != '1':
            return False

    for r, c in border_coords:
        if r > 0 and c > 0 and matrix[r - 1][c - 1] == '1':
            return False
        if r > 0 and c < len(matrix) and matrix[r - 1][c + 1] == '1':
            return False
        if r < len(matrix) and c > 0 and matrix[r + 1][c - 1] == '1':
