def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])
    costs = []
    for i in range(N):
        row = list(map(int, lines[i+1].split()))
        costs.append([0] + row + [0])

    if N % 2 != 0:
        return "-1\n"

    preferences = []
    for i in range(N):
        prefs = []
        for j in range(N):
            if i != j:
                prefs.append((j, costs[i][j]))
        prefs.sort(key=lambda x: x[1])
        preferences.append([p[0] for p in prefs])

    unmatched = set(range(N))
    engagements = {}
    next_proposal = {i: 0 for i in range(N)}
    proposals = {i: preferences[i][:N-1] for i in range(N)}

    while unmatched:
        person = next(iter(unmatched))
        if not proposals[person]:
            unmatched.discard(person)
            continue

        choice_idx = next_proposal[person]
        if choice_idx == len(proposals[person]):
            unmatched.discard(person)
            continue

        choice = preferences[person][choice_idx]

        next_proposal[person] += 1
        if choice not in engagements:
            engagements[choice] = person
            engagements[person] = choice
            unmatched.discard(person)
        else:
            current_match = engagements[choice]
            if person < current_match:
                engagements[choice] = person
                engagements[person] = choice
                unmatched.discard(person)
                unmatched.add(current_match)

    result = []
    for i in range(N):
        if i in engagements:
            result.append(engagements[i])
        else:
            result.append(-1)

    return '\n'.join(map(str, result)) + '\n'
