def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    p_set = set(p)

    # Build graph for constraints
    # Each node is a number, edges represent pairs that must be in same set
    graph = {}
    for num in p:
        comp_a = a - num
        if comp_a in p_set:
            if num not in graph:
                graph[num] = []
                graph[comp_a] = []
            graph[num].append(comp_a)
            graph[comp_a].append(num)

        comp_b = b - num
        if comp_b in p_set:
            if num not in graph:
                graph[num] = []
                graph[comp_b] = []
            graph[num].append(comp_b)
            graph[comp_b].append(num)

    # Color components with 0/1
    color = {}
    def dfs(node, c):
        color[node] = c
        for neighbor in graph[node]:
            if neighbor in p_set:
                if neighbor not in color:
                    dfs(neighbor, 1 - c)
                else:
                    if color[neighbor] == c:
                        return False
        return True

    possible = True
    uncolored = set(graph.keys())
    for node in list(uncolored):
        if node not in color:
            if not dfs(node, 0):
                possible = False
                break
        uncolored -= {k for k in uncolored if k in graph.get(node, [node])}

    if not possible:
        return "NO\n"

    # Build assignment
    result = []
    for num in p:
        result.append(str(color.get(num, 1)))

    return "YES\n" + " ".join(result) + "\n"
