import sys

MOD = 1051131

def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    m, t, s = int(parts[0]), int(parts[1]), int(parts[2])
    a = list(map(int, lines[1].split()))

    n = 2 * m

    # Generate all a values
    for i in range(s, n):
        a.append((101 * a[i - s] + 10007) % MOD)

    # Precompute bit_count for 1..2m
    def bit_count(x):
        return bin(x).count('1')

    # Matrix multiplication modulo MOD
    def mat_mul(A, B):
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if A[i][j] == 0:
                    continue
                for k in range(n):
                    if B[k][j] == 0:
                        continue
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    # Binary exponentiation for matrices
    def mat_pow(A, p):
        if p == 0:
            return [[0] * n for _ in range(n)]
        res = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = A[:]
        while p:
            if p & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            p >>= 1
        return res

    # Construct transition matrix
    # mat[i][j] = 2^(bit_count(gcd(i+1, j+1)))
    mat = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                mat[i][j] = 1
            else:
                g = math.gcd(i + 1, j + 1)
                mat[i][j] = 1 << bit_count(g)

    # Compute mat^(t-1)
    trans = mat_pow(mat, t - 1)

    # Compute answer = sum over i of sum over j of (ai * mat[i][j]) XOR all
    import math
    ans_xor = 0
    for i in range(n):
        term = 0
        for j in range(n):
            term = (term + a[i] * trans[i][j]) % MOD
        ans_xor ^= term

    return str(ans_xor)

